targets.expr:
sum by (usename) (
  pg_custom_activity_count{
    instance="$instance",
    datname=~"$datname",
    state="active"
  }
)

sum by (usename) (
  pg_custom_activity_count{
    instance="$instance",
    datname=~"$datname",
    state="idle"
  }
)

sum by (usename) (
  pg_custom_activity_count{
    instance="$instance",
    datname=~"$datname",
    state="idle in transaction"
  }
)

sum by (wait_event_type, wait_event) (
  pg_custom_activity_count{
    instance="$instance",
    datname=~"$datname",
    state="active",
    wait_event!="Running"
  }
)

sort_desc(
  pg_custom_index_size_bytes{
    instance="$instance",
    datname=~"$datname"
  }
  and on(instance, datname, schemaname, relname, idxname)
  (
    pg_custom_index_idx_scan{
      instance="$instance",
      datname=~"$datname"
    } == 0
  )
)

rate(
  pg_db_blks_hit{
    instance="$instance",
    datname=~"$datname",
    datname!~"template0|template1"
  }[5m]
)
/
(
  rate(
    pg_db_blks_hit{
      instance="$instance",
      datname=~"$datname",
      datname!~"template0|template1"
    }[5m]
  )
  +
  rate(
    pg_db_blks_read{
      instance="$instance",
      datname=~"$datname",
      datname!~"template0|template1"
    }[5m]
  )
)
